import java.io.*;
import java.util.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int bufLen, bufPtr;

    static int read() throws IOException {
        if (bufPtr == bufLen) {
            bufLen = System.in.read(BUF, 0, BUF.length);
            bufPtr = 0;
            if (bufLen <= 0) return -1;
        }
        return BUF[bufPtr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        long[][] items = new long[n][3];  // (end, start, profit)
        for (int i = 0; i < n; i++) items[i][1] = nextLong();
        for (int i = 0; i < n; i++) items[i][0] = items[i][1] + nextLong();
        for (int i = 0; i < n; i++) items[i][2] = nextLong();
        Arrays.sort(items, (x, y) -> x[0] != y[0] ? Long.compare(x[0], y[0])
                : x[1] != y[1] ? Long.compare(x[1], y[1]) : Long.compare(x[2], y[2]));
        long[] ends = new long[n], dp = new long[n + 1];
        for (int i = 0; i < n; i++) ends[i] = items[i][0];
        for (int i = 0; i < n; i++) {
            // Compatible intervals end strictly before this start (a shared endpoint overlaps).
            long start = items[i][1];
            int lo = 0, hi = i;
            while (lo < hi) {
                int mid = (lo + hi) >>> 1;
                if (ends[mid] < start) lo = mid + 1;
                else hi = mid;
            }
            dp[i + 1] = Math.max(dp[i], dp[lo] + items[i][2]);
        }
        System.out.println(dp[n]);
    }
}

package main

import (
	"cmp"
	"fmt"
	"io"
	"os"
	"slices"
)

var data []byte
var pos int

func nextInt() int64 {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n := int(nextInt())
	type interval struct{ end, start, value int64 }
	items := make([]interval, n)
	for i := range items {
		items[i].start = nextInt()
	}
	for i := range items {
		items[i].end = items[i].start + nextInt()
	}
	for i := range items {
		items[i].value = nextInt()
	}
	slices.SortFunc(items, func(x, y interval) int {
		return cmp.Or(cmp.Compare(x.end, y.end), cmp.Compare(x.start, y.start), cmp.Compare(x.value, y.value))
	})
	ends := make([]int64, n)
	for i, it := range items {
		ends[i] = it.end
	}
	dp := make([]int64, n+1)
	for i, it := range items {
		// Compatible intervals end strictly before this start (a shared endpoint overlaps).
		j, _ := slices.BinarySearch(ends[:i], it.start)
		dp[i+1] = max(dp[i], dp[j]+it.value)
	}
	fmt.Println(dp[n])
}
